@_guard
def import_csv(self, text, profile, apply_rules=True):
    from .csvimport import ImportProfile, import_csv, parse_profile
    from .rules import parse_rules

    with self._txn(True):
        if isinstance(profile, str):
            if _NAME_CHARS_RE.fullmatch(profile):
                profile = parse_profile(self._profile_text(profile))
            else:
                profile = parse_profile(profile)
        elif not isinstance(profile, ImportProfile):
            raise ValidationError("profile must be a profile name, profile text or an ImportProfile")
        rules = None
        if apply_rules:
            row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            if row and row[0].strip():
                rules = parse_rules(row[0])
        result = import_csv(text, profile, rules, self._load())
        outcome = ImportOutcome([], list(result.duplicates), list(result.errors))
        if result.errors or not result.transactions:
            return outcome
        counts = Counter(_import_key_base(tx) for tx in result.duplicates)
        keys = []
        for tx in result.transactions:
            base = _import_key_base(tx)
            counts[base] += 1
            keys.append("%s|%d" % (base, counts[base]))
        bulk = self.add_transactions(result.transactions, keys)
        outcome.added = bulk.added
        outcome.duplicates.extend(result.transactions[i] for i in bulk.skipped)
        return outcome

@_guard
