def _db_error(exc):
    text = str(exc)
    low = text.lower()
    if "locked" in low or "busy" in low:
        return ConflictError("database is locked: another process is writing to the book")
    return ConflictError("database error: %s" % text)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _need_text(value, what):
    if not isinstance(value, str):
        raise ValidationError("%s must be text, got '%s'" % (what, value))
    return value


def _fit(value, what):
    if not _INT_MIN <= value <= _INT_MAX:
        raise ValidationError("%s is too large to store in a book" % what)


def _parse_stored_date(text, what):
    try:
        return parse_date(text)
    except TallybookError:
        raise ConflictError("the book holds an invalid date '%s' (%s)" % (text, what)) from None


def _guard(fn):
    @functools.wraps(fn)
    def wrapper(self, *args, **kwargs):
        with self._lock:
            self._check_usable()
            try:
                return fn(self, *args, **kwargs)
            except sqlite3.Error as exc:
                raise _db_error(exc) from None
            except OverflowError:
                raise ValidationError("a number is too large to store in a book") from None
            except UnicodeEncodeError:
                raise ValidationError("text cannot be stored in a book (invalid characters)") from None

    return wrapper


def _import_key_base(tx):
    first = tx.postings[0]
    return "%s|%s|%s|%d %s" % (
        format_date(tx.date), tx.payee, first.account, first.amount.minor, first.amount.currency
    )


class Store:
    def __init__(self, path, fspath, conn):
        self.path = path
        self._fspath = fspath
        self._conn = conn
        self._lock = threading.RLock()
        self._closed = False
        self._in_tx = False
        self._version = conn.execute("PRAGMA user_version").fetchone()[0]

    # -- opening ---------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        try:
            fspath = os.fspath(path)
        except TypeError:
            raise ValidationError("path must be text or a path object, got '%s'" % (path,)) from None
        if isinstance(fspath, bytes):
            fspath = os.fsdecode(fspath)
        if not fspath:
            raise NotFoundError("no such book file ''")
        if os.path.isdir(fspath):
            raise ConflictError("'%s' is a directory, not a book" % fspath)
        existed = os.path.exists(fspath)
        if not existed:
            if not create:
                raise NotFoundError("no such book file '%s'" % fspath)
            parent = os.path.dirname(os.path.abspath(fspath))
            if not os.path.isdir(parent):
                raise NotFoundError("the directory for '%s' does not exist" % fspath)
        try:
            conn = sqlite3.connect(
                fspath, timeout=BUSY_TIMEOUT, isolation_level=None, check_same_thread=False
            )
        except sqlite3.Error as exc:
            raise ConflictError("cannot open '%s': %s" % (fspath, exc)) from None
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT count(*) FROM sqlite_master").fetchone()[0]
        except sqlite3.Error as exc:
            conn.close()
            if not existed:
                cls._discard(fspath)
            raise ConflictError("'%s' is not a tallybook book: %s" % (fspath, exc)) from None
        if version == 0 and tables > 0:
            conn.close()
            raise ConflictError("'%s' is not a tallybook book: it has tables but no version" % fspath)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError(
                "'%s' is at version %d, newer than this tool (version %d)" % (fspath, version, LATEST_VERSION)
            )
        store = cls(path, fspath, conn)
        if version == 0 and create:
            try:
                store.migrate()
            except BaseException:
                store.close()
                if not existed:
                    cls._discard(fspath)
                raise
        return store

    @staticmethod
    def _discard(fspath):
        for suffix in ("", "-journal"):
            with contextlib.suppress(OSError):
                os.unlink(fspath + suffix)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            with contextlib.suppress(sqlite3.Error):
                self._conn.close()

    def _check_usable(self):
        if self._closed:
            raise ConflictError("the book is closed")
        if self._version != LATEST_VERSION:
            self._version = self._read_version()
        if self._version != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % self._version)

    def _read_version(self):
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.Error as exc:
            raise _db_error(exc) from None

    @property
    def version(self):
        with self._lock:
            if self._closed:
                raise ConflictError("the book is closed")
            if self._version != LATEST_VERSION:
                self._version = self._read_version()
            return self._version

    # -- transactions ----------------------------------------------------
    @contextlib.contextmanager
    def _txn(self, write):
        if self._in_tx:
            raise NotFoundError("no such account '%s'" % (path,))
        return chart.get(path)

    @_guard
    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._txn(True):
            chart, _ = self._load_chart()
            acct = chart.add(path, type, currency, opened, note)
            self._conn.execute(
                "INSERT INTO accounts (path, type, currency, opened, note) VALUES (?, ?, ?, ?, ?)",
                (acct.path, acct.type, acct.currency, format_date(opened) if opened else None, acct.note),
            )
            return acct

    @_guard
    def get_account(self, path):
        with self._txn(False):
            chart, paths = self._load_chart()
            return self._stored_account(chart, paths, path)

    @_guard
    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return self._accounts(type, under, currency, include_closed)

    def _accounts(self, type, under, currency, include_closed):
        if type is not None and (not isinstance(type, str) or type not in TYPES):
            raise ValidationError("unknown account type '%s'" % (type,))
        if under is not None:
            _need_text(under, "under")
        if currency is not None:
            _need_text(currency, "currency")
        chart, paths = self._load_chart()
        out = []
        for path in sorted(paths):
            acct = chart.get(path)
            if type is not None and acct.type != type:
                continue
            if under is not None and not (path == under or path.startswith(under + ":")):
                continue
            if currency is not None and acct.currency != currency:
                continue
            if not include_closed and acct.closed is not None:
                continue
            out.append(acct)
        return out

    @_guard
    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return len(self._accounts(type, under, currency, include_closed))

    @_guard
    def chart(self):
        with self._txn(False):
            return self._load_chart()[0]

    @_guard
    def close_account(self, path, on):
        with self._txn(True):
            chart, paths = self._load_chart()
            self._stored_account(chart, paths, path)
            acct = chart.close(path, on)
            latest = self._conn.execute(
                "SELECT max(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id WHERE p.account = ?",
                (path,),
            ).fetchone()[0]
            if latest is not None and latest > format_date(on):
                raise ConflictError(
                    "cannot close account %s on %s: it has a posting on %s" % (path, format_date(on), latest)
                )
            self._conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
            return acct

    @_guard
    def set_account_note(self, path, note):
        _need_text(note, "note")
        with self._txn(True):
            chart, paths = self._load_chart()
            acct = self._stored_account(chart, paths, path)
            self._conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            acct.note = note
            return acct

    @_guard
    def delete_account(self, path):
        with self._txn(True):
            _, paths = self._load_chart()
            if not isinstance(path, str) or path not in paths:
                raise NotFoundError("no such account '%s'" % (path,))
            used = self._conn.execute("SELECT count(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]
            if used:
                raise ConflictError("account %s cannot be deleted: %d posting(s) use it" % (path, used))
            self._conn.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # -- transactions ----------------------------------------------------
    def _load(self, cond="", params=(), limit=None, offset=0):
        lim = -1 if limit is None else min(limit, _INT_MAX)
        off = min(offset, _INT_MAX)
        sub = "SELECT id FROM transactions %s ORDER BY date, id LIMIT ? OFFSET ?" % cond
        args = tuple(params) + (lim, off)
    def has_import_key(self, key):
        if not isinstance(key, str):
            return False
        with self._txn(False):
            return self._has_key(key)

    @staticmethod
    def _check_paging(limit, offset):
        if limit is not None and (not _is_int(limit) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0, got '%s'" % (limit,))
        if not _is_int(offset) or offset < 0:
            raise ValidationError("offset must be a whole number of at least 0, got '%s'" % (offset,))

    def _parse_query(self, query):
        if query is None:
            return None
        from .query import parse_query

        if isinstance(query, str):
            if not query.strip():
                return None
            return parse_query(query, self._load_chart()[0])
        if hasattr(query, "matches") and hasattr(query, "is_empty"):
            return None if query.is_empty else query
        raise ValidationError("query must be text or a parsed query, got '%s'" % (query,))

    @_guard
    def transactions(self, query=None, limit=None, offset=0):
        self._check_paging(limit, offset)
        with self._txn(False):
            q = self._parse_query(query)
            if q is None:
                return self._load("", (), limit, offset)
            from .query import select

            chosen = select(self._load(), q)
            return chosen[offset:] if limit is None else chosen[offset : offset + limit]

    @_guard
    def count_transactions(self, query=None):
        with self._txn(False):
            q = self._parse_query(query)
            if q is None:
                return self._conn.execute("SELECT count(*) FROM transactions").fetchone()[0]
            from .query import select

            return len(select(self._load(), q))

    @staticmethod
    def _need_id(tx_id):
        if not _is_int(tx_id):
            raise ValidationError("transaction id must be a whole number, got '%s'" % (tx_id,))

    @_guard
    def get_transaction(self, id):
        self._need_id(id)
        with self._txn(False):
            found = self._load("WHERE id = ?", (id,)) if _INT_MIN <= id <= _INT_MAX else []
            if not found:
                raise NotFoundError("no transaction %s" % id)
            return found[0]

    @_guard
    def delete_transaction(self, id):
        self._need_id(id)
        with self._txn(True):
            found = self._load("WHERE id = ?", (id,)) if _INT_MIN <= id <= _INT_MAX else []
            if not found:
                raise NotFoundError("no transaction %s" % id)
            for table in ("import_keys", "tags", "postings"):
                self._conn.execute("DELETE FROM %s WHERE tx_id = ?" % table, (id,))
            self._conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
            return found[0]

    def _build_ledger(self):
        chart, _ = self._load_chart()
        led = Ledger(chart, self._load_rates())
        for tx in self._load():
