def _recurring_rows(self):
    from .recurring import Recurring

    out = []
    rows = self._conn.execute(
        "SELECT name, schedule, template, start_date, end_date, max_count, materialized_through"
        " FROM recurring ORDER BY name"
    ).fetchall()
    for name, schedule, template, start, end, count, through in rows:
        try:
            rec = Recurring(
                name,
                schedule,
                self._template_from_json(template),
                _parse_stored_date(start, "recurring %s" % name),
                _parse_stored_date(end, "recurring %s" % name) if end else None,
                count,
            )
        except ConflictError:
            raise
        except (TallybookError, ValueError) as exc:
            raise ConflictError(
                "the book holds an invalid recurring item '%s': %s" % (name, getattr(exc, "message", exc))
            ) from None
        out.append((rec, _parse_stored_date(through, "recurring %s" % name) if through else None))
    return out

@_guard
def recurring(self):
    with self._txn(False):
        return [rec for rec, _ in self._recurring_rows()]

@_guard
def materialized_through(self, name):
    _need_text(name, "name")
    with self._txn(False):
        row = self._conn.execute(
            "SELECT materialized_through FROM recurring WHERE name = ?", (name,)
        ).fetchone()
        if row is None:
            raise NotFoundError("no recurring item '%s'" % name)
        return _parse_stored_date(row[0], "recurring %s" % name) if row[0] else None

@_guard
def materialize(self, upto=None, today=None):
    for value, what in ((upto, "upto"), (today, "today")):
        if value is not None and not is_date(value):
            raise ValidationError("%s must be a date, got '%s'" % (what, value))
    given = [d for d in (upto, today) if d is not None]
    if not given:
        raise ValidationError("materialize needs a date: give upto or today")
    horizon = min(given)
    from .recurring import instantiate, occurrences

    with self._txn(True):
        pending = []
        advance = []
        for rec, through in self._recurring_rows():
            if through is not None and horizon <= through:
                continue
            lo = rec.start if through is None else through + timedelta(days=1)
            for day in occurrences(rec, lo, horizon):
                pending.append((day, rec.name, instantiate(rec, day)))
            advance.append(rec.name)
        pending.sort(key=lambda item: (item[0], item[1]))
        led, paths = self._ledger_for_adding()
        made = [self._insert(self._validated(led, paths, tx)) for _, _, tx in pending]
        for name in advance:
            self._conn.execute(
                "UPDATE recurring SET materialized_through = ? WHERE name = ?", (format_date(horizon), name)
            )
        return made

