import json
import re
from urllib.parse import unquote_to_bytes

from ..errors import ParseError, ValidationError
from ..export import to_json

MAX_BODY = 1048576
INT_MAX = 9223372036854775807
JSON_TYPE = "application/json"
TEXT_TYPES = ("text/csv", "text/plain")

_DIGITS = re.compile(r"[0-9]+")
_YES = ("true", "yes", "1")
_NO = ("false", "no", "0")


class HttpError(Exception):
    """An answer decided by the API itself (status, message, optional Allow header)."""

    def __init__(self, status, message, allow=None):
        super().__init__(message)
        self.status = status
        self.message = message
        self.allow = allow


class Answer:
    def __init__(self, status, content_type, body):
        self.status = status
        self.content_type = content_type
        self.body = body
        self.allow = None


def encode(text):
    return text.encode("utf-8", "replace")


def json_answer(status, value):
    return Answer(status, "application/json; charset=utf-8", encode(to_json(value)))


def text_answer(text, content_type="text/plain"):
    return Answer(200, content_type + "; charset=utf-8", encode(text))


def error_answer(status, message, allow=None):
    answer = json_answer(status, {"error": message or "error"})
    answer.allow = allow
    return answer


def status_for(exc):
    code = getattr(exc, "code", "")
    if code == "not_found":
        return 404
    if code == "conflict":
        return 409
    return 400


