def _decode(raw):
    """Percent-decode text that was read as latin-1 (so it holds the original bytes); None if not UTF-8."""
    try:
        return unquote_to_bytes(raw.encode("latin-1", "replace")).decode("utf-8")
    except UnicodeDecodeError:
        return None


def split_target(target):
    """(pieces, query_string) of a request target; pieces is None for a path nothing can match."""
    cut = target.find("#")
    if cut >= 0:
        target = target[:cut]
    path, _, qs = target.partition("?")
    if not path.startswith("/"):
        return None, qs
    pieces = []
    for raw in path[1:].split("/"):
        if raw == "":
            return None, qs
        piece = _decode(raw)
        if piece is None:
            return None, qs
        pieces.append(piece)
    return pieces, qs


def digits_id(text):
    """The integer of an id piece (digits only), or None when it cannot name a stored transaction."""
    if not _DIGITS.fullmatch(text):
        return None
    text = text.lstrip("0")
    if len(text) > 19:
        return None
    return int(text or "0")


# ---------------------------------------------------------------- query
class Query:
    def __init__(self, qs):
        self._raw = {}
        for part in qs.split("&"):
            if not part:
                continue
            name, _, value = part.partition("=")
            name = unquote_to_bytes(name.replace("+", " ").encode("latin-1", "replace")).decode("utf-8", "replace")
            self._raw[name] = value

    def text(self, name, required=False):
        raw = self._raw.get(name)
        if raw is None:
            if required:
                raise ValidationError("missing query parameter: %s" % name)
            return None
        value = _decode(raw.replace("+", " "))
        if value is None:
            raise ParseError("query parameter %s is not valid UTF-8" % name)
        return value

    def yes_no(self, name, default):
        value = self.text(name)
        if value is None:
            return default
        low = value.lower() if value.isascii() else value
        if low in _YES:
            return True
        if low in _NO:
            return False
        raise ValidationError("query parameter %s must be true, false, yes, no, 1 or 0, got '%s'" % (name, value))

    def whole(self, name, default):
        value = self.text(name)
        if value is None:
            return default
        digits = value.lstrip("0") if _DIGITS.fullmatch(value) else None
        if digits is None or len(digits) > 19 or int(digits or "0") > INT_MAX:
            raise ValidationError(
                "query parameter %s must be a whole number from 0 to %d, got '%s'" % (name, INT_MAX, value[:100])
