"""Checking the fields of a JSON request body and building library objects from them."""
from ..dates import parse_date
from ..errors import ValidationError
from ..model import Posting, Transaction
from ..money import Money


def text(value, name):
    if not isinstance(value, str):
        raise ValidationError("field %s must be text" % name)
    return value


def boolean(value, name):
    if not isinstance(value, bool):
        raise ValidationError("field %s must be true or false" % name)
    return value


def whole(value, name):
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValidationError("field %s must be a whole number" % name)
    return value


def date(value, name):
    return parse_date(text(value, name))


def obj(value, name):
    if not isinstance(value, dict):
        raise ValidationError("field %s must be an object" % name)
    return value


def tags(value, name):
    if not isinstance(value, list) or not all(isinstance(t, str) for t in value):
        raise ValidationError("field %s must be a list of text" % name)
    return tuple(value)


def amount(value, name):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"} or not all(isinstance(v, str) for v in value.values()):
            raise ValidationError(
                "field %s must be an object with the text fields amount and currency, or text like '12.50 USD'" % name
            )
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("field %s must be an object with amount and currency, or text like '12.50 USD'" % name)


def read(body, spec, where="request body"):
    """Validate a JSON object against spec {name: (reader, required)}; null counts as absent.

    Returns a dict holding only the fields that are present."""
    if not isinstance(body, dict):
        raise ValidationError("%s must be a JSON object" % where)
    for key in body:
        if key not in spec:
            raise ValidationError("unknown field: %s" % key if where == "request body" else "%s: unknown field: %s" % (where, key))
    out = {}
    for name, (reader, required) in spec.items():
        value = body.get(name)
        if value is None:
            if required:
                raise ValidationError("missing field: %s" % name if where == "request body" else "%s: missing field: %s" % (where, name))
            continue
        out[name] = reader(value, name)
    return out


def _postings(value, name):
    if not isinstance(value, list):
        raise ValidationError("field %s must be a list of objects" % name)
    out = []
    for i, item in enumerate(value, 1):
        got = read(item, POSTING, "posting %d" % i)
        out.append(Posting(got["account"], got.get("amount"), got.get("note", "")))
    return out


POSTING = {"account": (text, True), "amount": (amount, False), "note": (text, False)}
TX_BODY = {"payee": (text, True), "narration": (text, False), "flag": (text, False), "tags": (tags, False),
           "postings": (_postings, True)}


def transaction(body, on=None):
    """A Transaction from a request object; with `on` (a date) the body has no `date` field."""
    spec = dict(TX_BODY)
    if on is None:
        spec["date"] = (date, True)
    got = read(body, spec)
    return Transaction(
        on if on is not None else got["date"],
        got["payee"],
        got.get("narration", ""),
        got["postings"],
        got.get("tags", ()),
        got.get("flag", "*"),
    )

