"""The endpoints: path table and one handler per verb. Handlers return an `Answer`."""
import datetime

from .. import __version__
from ..budgets import Budget, budget_status
from ..dates import Period, format_date, parse_date
from ..errors import NotFoundError, ValidationError
from ..export import money_to_dict, transaction_to_dict, transactions_to_csv, transactions_to_json
from ..journal import format_journal
from ..recurring import Recurring
from ..reports import (balance_sheet, cashflow, income_statement, register, render_text, trial_balance)
from ..storage import Store
from . import fields
from .protocol import JSON_TYPE, TEXT_TYPES, Answer, digits_id, json_answer, text_answer


# ---------------------------------------------------------------- shapes
def _day(d):
    return None if d is None else format_date(d)


def account_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency, "opened": _day(a.opened),
            "closed": _day(a.closed), "note": a.note}


def rate_dict(src, dst, on, text):
    return {"src": src, "dst": dst, "date": _day(on), "rate": text}


def budget_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": _day(b.start)}


def recurring_dict(rec):
    t = rec.template
    return {
        "name": rec.name,
        "schedule": str(rec.schedule),
        "start": _day(rec.start),
        "end": _day(rec.end),
        "count": rec.count,
        "template": {
            "payee": t.payee,
            "narration": t.narration,
            "flag": t.flag,
            "tags": sorted(set(t.tags)),
            "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                         for p in t.postings],
        },
    }


def _store(req):
    return Store.open(req.db_path)


# ---------------------------------------------------------------- health
def health(req):
    with _store(req) as store:
        return json_answer(200, {"status": "ok", "version": __version__, "schema_version": store.version})


# ---------------------------------------------------------------- accounts
def accounts_list(req):
    q = req.query
    kind, under, cur = q.text("type"), q.text("under"), q.text("currency")
    include_closed = q.yes_no("include_closed", True)
    with _store(req) as store:
        found = store.accounts(type=kind, under=under, currency=cur, include_closed=include_closed)
    return json_answer(200, [account_dict(a) for a in found])


def accounts_add(req):
    got = fields.read(req.obj, {
        "path": (fields.text, True), "type": (fields.text, False), "currency": (fields.text, False),
        "opened": (fields.date, False), "note": (fields.text, False),
    })
    with _store(req) as store:
        acct = store.add_account(got["path"], got.get("type"), got.get("currency"), got.get("opened"),
                                 got.get("note", ""))
    return json_answer(201, account_dict(acct))


def account_get(req, path):
    with _store(req) as store:
        return json_answer(200, account_dict(store.get_account(path)))


def account_close(req, path):
    got = fields.read(req.obj, {"on": (fields.date, False)})
    on = got.get("on") or req.today
    with _store(req) as store:
        return json_answer(200, account_dict(store.close_account(path, on)))


# ---------------------------------------------------------------- transactions
def transactions_list(req):
    q = req.query
    query, limit, offset = q.text("q"), q.whole("limit", None), q.whole("offset", 0)
    with _store(req) as store:
        every = store.transactions(query)
    kept = every[offset:] if limit is None else every[offset:offset + limit]
    return json_answer(200, {"items": [transaction_to_dict(t) for t in kept], "total": len(every),
                             "limit": limit, "offset": offset})


def transactions_add(req):
    tx = fields.transaction(req.obj)
    with _store(req) as store:
        return json_answer(201, transaction_to_dict(store.add_transaction(tx)))


def _tx_id(piece):
    tx_id = digits_id(piece)
    if tx_id is None:
        raise NotFoundError("no transaction %s" % piece[:50])
    return tx_id


def transaction_get(req, piece):
    tx_id = _tx_id(piece)
    with _store(req) as store:
        return json_answer(200, transaction_to_dict(store.get_transaction(tx_id)))


def transaction_delete(req, piece):
