        found = store.accounts(type=kind, under=under, currency=cur, include_closed=include_closed)
    return json_answer(200, [account_dict(a) for a in found])


def accounts_add(req):
    got = fields.read(req.obj, {
        "path": (fields.text, True), "type": (fields.text, False), "currency": (fields.text, False),
        "opened": (fields.date, False), "note": (fields.text, False),
    })
    with _store(req) as store:
        acct = store.add_account(got["path"], got.get("type"), got.get("currency"), got.get("opened"),
                                 got.get("note", ""))
    return json_answer(201, account_dict(acct))


def account_get(req, path):
    with _store(req) as store:
        return json_answer(200, account_dict(store.get_account(path)))


def account_close(req, path):
    got = fields.read(req.obj, {"on": (fields.date, False)})
    on = got.get("on") or req.today
    with _store(req) as store:
        return json_answer(200, account_dict(store.close_account(path, on)))


# ---------------------------------------------------------------- transactions
def transactions_list(req):
    q = req.query
    query, limit, offset = q.text("q"), q.whole("limit", None), q.whole("offset", 0)
    with _store(req) as store:
        every = store.transactions(query)
    kept = every[offset:] if limit is None else every[offset:offset + limit]
    return json_answer(200, {"items": [transaction_to_dict(t) for t in kept], "total": len(every),
                             "limit": limit, "offset": offset})


def transactions_add(req):
    tx = fields.transaction(req.obj)
    with _store(req) as store:
        return json_answer(201, transaction_to_dict(store.add_transaction(tx)))


def _tx_id(piece):
    tx_id = digits_id(piece)
    if tx_id is None:
        raise NotFoundError("no transaction %s" % piece[:50])
    return tx_id


def transaction_get(req, piece):
    tx_id = _tx_id(piece)
    with _store(req) as store:
        return json_answer(200, transaction_to_dict(store.get_transaction(tx_id)))


def transaction_delete(req, piece):
    tx_id = _tx_id(piece)
    with _store(req) as store:
        return json_answer(200, transaction_to_dict(store.delete_transaction(tx_id)))


# ---------------------------------------------------------------- rates
def rates_list(req):
    with _store(req) as store:
        rows = store.rate_rows()
    return json_answer(200, [rate_dict(*row) for row in rows])


def rates_put(req):
    got = fields.read(req.obj, {
        "src": (fields.text, True), "dst": (fields.text, True), "date": (fields.date, True),
        "rate": (fields.text, True),
    })
    with _store(req) as store:
        store.set_rate(got["src"], got["dst"], got["rate"], got["date"])
    return json_answer(200, rate_dict(got["src"], got["dst"], got["date"], got["rate"]))


def rates_delete(req):
    q = req.query
    src, dst = q.text("src", True), q.text("dst", True)
    on = parse_date(q.text("date", True))
    with _store(req) as store:
        found = [row for row in store.rate_rows() if row[0] == src and row[1] == dst and row[2] == on]
        store.remove_rate(src, dst, on)
    return json_answer(200, rate_dict(*found[0]))


# ---------------------------------------------------------------- budgets
def budgets_list(req):
    with _store(req) as store:
        found = store.budgets()
    return json_answer(200, [budget_dict(b) for b in found])


def budgets_add(req):
    got = fields.read(req.obj, {
        "pattern": (fields.text, True), "period_kind": (fields.text, True), "amount": (fields.amount, True),
        "start": (fields.date, True),
    })
    budget = Budget(got["pattern"], got["period_kind"], got["amount"], got["start"])
    with _store(req) as store:
        store.add_budget(budget)
    return json_answer(201, budget_dict(budget))


def budgets_delete(req):
    pattern, kind = req.query.text("pattern", True), req.query.text("period_kind", True)
    with _store(req) as store:
        found = [b for b in store.budgets() if b.pattern == pattern and b.period_kind == kind]
        store.remove_budget(pattern, kind)
    return json_answer(200, budget_dict(found[0]))


def budgets_status(req):
    period = Period.parse(req.query.text("period", True))
    with _store(req) as store:
        budgets = store.budgets()
        ledger = store.ledger()
    return json_answer(200, [line.to_dict() for line in budget_status(budgets, ledger, period)])


# ---------------------------------------------------------------- recurring
def recurring_list(req):
    with _store(req) as store:
        found = store.recurring()
    return json_answer(200, [recurring_dict(r) for r in found])


def recurring_add(req):
    got = fields.read(req.obj, {
        "name": (fields.text, True), "schedule": (fields.text, True), "start": (fields.date, True),
        "template": (fields.obj, True), "end": (fields.date, False), "count": (fields.whole, False),
    })
    template = fields.transaction(got["template"], on=got["start"])
    rec = Recurring(got["name"], got["schedule"], template, got["start"], got.get("end"), got.get("count"))
    with _store(req) as store:
        store.add_recurring(rec)
    return json_answer(201, recurring_dict(rec))


def recurring_delete(req):
    name = req.query.text("name", True)
    with _store(req) as store:
        found = [r for r in store.recurring() if r.name == name]
        store.remove_recurring(name)
    return json_answer(200, recurring_dict(found[0]))


def recurring_materialize(req):
    got = fields.read(req.obj, {"upto": (fields.date, False)})
    with _store(req) as store:
        made = store.materialize(upto=got.get("upto"), today=req.today)
    return json_answer(200, {"added": [transaction_to_dict(t) for t in made]})


# ---------------------------------------------------------------- reports
def _report_format(q):
    return q.choice("format", ("json", "text"), "json")


def _as_of(q):
    value = q.text("as_of")
    return None if value is None else parse_date(value)


def _period(q, required=True):
    value = q.text("period", required)
    return None if value is None else Period.parse(value)


def report(req, name):
    q = req.query
    fmt = _report_format(q)
    if name == "trial-balance":
        as_of = _as_of(q)
        build = lambda led: trial_balance(led, as_of)  # noqa: E731
    elif name == "balance-sheet":
        as_of, convert = _as_of(q), q.text("convert_to")
        build = lambda led: balance_sheet(led, as_of, convert, req.today)  # noqa: E731
    elif name == "income-statement":
        period, convert = _period(q), q.text("convert_to")
        build = lambda led: income_statement(led, period, convert)  # noqa: E731
    elif name == "cashflow":
        period = _period(q)
        build = lambda led: cashflow(led, period)  # noqa: E731
    else:
        account = q.text("account", True)
        period = _period(q, required=False)
        rollup = q.yes_no("rollup", False)
        build = lambda led: register(led, account, period, rollup)  # noqa: E731
    with _store(req) as store:
        result = build(store.ledger())
    if fmt == "text":
        return text_answer(render_text(result))
    return json_answer(200, result)


# ---------------------------------------------------------------- import, rules, export
def import_csv(req):
    if req.obj is not None:
        got = fields.read(req.obj, {
            "csv": (fields.text, True), "profile": (fields.text, True), "apply_rules": (fields.boolean, False),
        })
        csv_text, profile, apply = got["csv"], got["profile"], got.get("apply_rules", True)
    else:
        profile = req.query.text("profile", True)
        apply = req.query.yes_no("apply_rules", True)
        from .protocol import parse_text_body

        csv_text = parse_text_body(req.body)
    with _store(req) as store:
        outcome = store.import_csv(csv_text, profile, apply)
    if outcome.errors:
        raise ValidationError("import failed: " + "; ".join("row %s: %s" % (n, msg) for n, msg in outcome.errors))
    return json_answer(200, {"added": [transaction_to_dict(t) for t in outcome.added],
                             "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]})


def rules_get(req):
    with _store(req) as store:
        return json_answer(200, {"rules": store.rules_text()})


def rules_put(req):
    got = fields.read(req.obj, {"rules": (fields.text, True)})
    with _store(req) as store:
        store.set_rules(got["rules"])
    return json_answer(200, {"rules": got["rules"]})


def export(req):
    fmt = req.query.choice("format", ("json", "csv", "journal"), "json")
    with _store(req) as store:
        if fmt == "journal":
            return text_answer(format_journal(store.journal()))
        txs = store.transactions()
    if fmt == "csv":
        return text_answer(transactions_to_csv(txs), "text/csv")
    return Answer(200, "application/json; charset=utf-8", transactions_to_json(txs).encode("utf-8", "replace"))


# ---------------------------------------------------------------- routing
JSON = (JSON_TYPE,)
IMPORT = (JSON_TYPE,) + TEXT_TYPES

REPORT_NAMES = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")

# path shape -> {verb: (handler, accepted body types)}
_FIXED = {
    ("health",): {"GET": (health, ())},
    ("accounts",): {"GET": (accounts_list, ()), "POST": (accounts_add, JSON)},
    ("transactions",): {"GET": (transactions_list, ()), "POST": (transactions_add, JSON)},
    ("rates",): {"DELETE": (rates_delete, ()), "GET": (rates_list, ()), "PUT": (rates_put, JSON)},
    ("budgets",): {"DELETE": (budgets_delete, ()), "GET": (budgets_list, ()), "POST": (budgets_add, JSON)},
    ("budgets", "status"): {"GET": (budgets_status, ())},
    ("recurring",): {"DELETE": (recurring_delete, ()), "GET": (recurring_list, ()), "POST": (recurring_add, JSON)},
    ("recurring", "materialize"): {"POST": (recurring_materialize, JSON)},
    ("import",): {"POST": (import_csv, IMPORT)},
    ("rules",): {"GET": (rules_get, ()), "PUT": (rules_put, JSON)},
    ("export",): {"GET": (export, ())},
}


def resolve(pieces):
    """(verbs, args) for a path, or None when no such path exists."""
    key = tuple(pieces)
    if key in _FIXED:
        return _FIXED[key], ()
    n = len(pieces)
    head = pieces[0]
    if head == "accounts" and n == 2:
        return {"GET": (account_get, ())}, (pieces[1],)
    if head == "accounts" and n == 3 and pieces[2] == "close":
        return {"POST": (account_close, JSON)}, (pieces[1],)
    if head == "transactions" and n == 2 and digits_id(pieces[1]) is not None:
        return {"DELETE": (transaction_delete, ()), "GET": (transaction_get, ())}, (pieces[1],)
    if head == "reports" and n == 2 and pieces[1] in REPORT_NAMES:
        return {"GET": (report, ())}, (pieces[1],)
    return None


def today_of(value):
    return value if value is not None else datetime.date.today()

