"""The HTTP API server: `serve(db_path, host, port, today)`."""
import datetime
import http.client
import re
import signal
import socket
import socketserver
import sys
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from ..errors import ConflictError, TallybookError, ValidationError
from ..storage import Store
from . import routes
from .protocol import (MAX_BODY, HttpError, Query, Request, error_answer, json_answer, media_type, parse_json,
                       split_target, status_for, JSON_TYPE)

MAX_LINE = 65536
DRAIN_SECONDS = 20.0
IDLE_TIMEOUT = 30
SHUTDOWN_WAIT = 2.0

_REQUEST_LINE = re.compile(r"([^\s]+) ([^\s]+) HTTP/(\d+)\.(\d+)")
_DIGITS = re.compile(r"[0-9]+")


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    request_queue_size = 128

    def __init__(self, address, handler, db_path, today):
        self.db_path = db_path
        self.today = today
        self._busy = 0
        self._idle = threading.Condition()
        super().__init__(address, handler)

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = str(host)
        self.server_port = port

    def handle_error(self, request, client_address):
        pass

    def begin(self):
        with self._idle:
            self._busy += 1

    def end(self):
        with self._idle:
            self._busy -= 1
            self._idle.notify_all()

    def wait_idle(self, seconds):
        deadline = time.monotonic() + seconds
        with self._idle:
            while self._busy > 0:
                left = deadline - time.monotonic()
                if left <= 0:
                    return
                self._idle.wait(left)


class _Server6(_Server):
    address_family = socket.AF_INET6


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "tallybook"
    sys_version = ""
    timeout = IDLE_TIMEOUT

    def log_message(self, format, *args):
        pass

    # one request per connection ------------------------------------------
    def handle(self):
        self.close_connection = True
        try:
            self._request()
        except OSError:
            pass

    def _request(self):
        line = self.rfile.readline(MAX_LINE + 1)
        if not line:
            return
        if len(line) > MAX_LINE or not line.endswith(b"\n"):
            self._send(error_answer(400, "the request line is too long or unreadable"), False)
            return
        text = line.decode("latin-1").rstrip("\r\n")
        match = _REQUEST_LINE.fullmatch(text)
        if match is None or match.group(3) != "1":
            self._send(error_answer(400, "unreadable request line"), False)
            return
        method, target = match.group(1), match.group(2)
        try:
            headers = http.client.parse_headers(self.rfile)
        except (http.client.HTTPException, ValueError):
            self._send(error_answer(400, "unreadable request headers"), False)
            return
        self._dispatch(method, target, headers, match.group(4) == "1")

    def _content_length(self, headers):
        values = headers.get_all("Content-Length") or []
        if not values:
            return 0
        values = [v.strip() for v in values]
        if len(set(values)) != 1 or not _DIGITS.fullmatch(values[0]):
            raise HttpError(400, "Content-Length is not a whole number")
        return int(values[0]) if len(values[0]) < 30 else 10 ** 30

    def _dispatch(self, method, target, headers, http11):
        unread = 0
        head = method == "HEAD"
        busy = False
        try:
            length = unread = self._content_length(headers)
            pieces, qs = split_target(target)
            found = routes.resolve(pieces) if pieces is not None else None
            if found is None:
                raise HttpError(404, "no such path")
            verbs, args = found
            if method not in verbs:
                raise HttpError(405, "method %s is not allowed here" % method[:50], ", ".join(sorted(verbs)))
            handler, accepted = verbs[method]
            body, obj = b"", None
            if method in ("POST", "PUT"):
                if headers.get("Transfer-Encoding") is not None:
                    raise HttpError(400, "chunked request bodies are not supported")
                if length > MAX_BODY:
                    raise HttpError(413, "the request body is over %d bytes" % MAX_BODY)
                if length:
                    kind = media_type(headers.get("Content-Type"))
                    if kind not in accepted:
                        raise HttpError(415, "unsupported Content-Type: expected %s" % " or ".join(accepted))
                    if http11 and (headers.get("Expect") or "").lower() == "100-continue":
                        self.wfile.write(b"HTTP/1.1 100 Continue\r\n\r\n")
                    body = self.rfile.read(length)
                    unread = 0
                    if len(body) < length:
                        return
                    if kind == JSON_TYPE:
                        obj = parse_json(body)
                elif JSON_TYPE in accepted and accepted == (JSON_TYPE,):
                    obj = {}
                elif accepted and headers.get("Content-Type") is not None and \
                        media_type(headers.get("Content-Type")) == JSON_TYPE:
                    obj = {}
            req = Request(method, pieces, Query(qs), body, obj, self.server.db_path,
                          self.server.today if self.server.today is not None else datetime.date.today())
            self.server.begin()
            busy = True
            answer = handler(req, *args)
        except HttpError as exc:
            answer = error_answer(exc.status, exc.message, exc.allow)
        except TallybookError as exc:
            answer = error_answer(status_for(exc), exc.message)
        except (OverflowError, ValueError, RecursionError) as exc:
            answer = error_answer(400, "invalid request: %s" % str(exc)[:200])
        except Exception:
            answer = error_answer(500, "internal error")
        finally:
            if busy:
                self.server.end()
        self._send(answer, head, unread)

    # answers --------------------------------------------------------------
    def _send(self, answer, head, unread=0):
        reason = HTTPStatus(answer.status).phrase
        lines = [
            "HTTP/1.1 %d %s" % (answer.status, reason),
            "Server: tallybook",
            "Date: %s" % self.date_time_string(),
            "Content-Type: %s" % answer.content_type,
            "Content-Length: %d" % len(answer.body),
            "Connection: close",
        ]
        if answer.allow:
            lines.append("Allow: %s" % answer.allow)
        data = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1")
        if not head:
            data += answer.body
        self.wfile.write(data)
        if unread:
            self._drain(unread)

    def _drain(self, remaining):
        """Read and drop the rest of a body we answered without reading, so the answer is not lost."""
        try:
            self.wfile.flush()
            self.connection.shutdown(socket.SHUT_WR)
        except OSError:
            return
        deadline = time.monotonic() + DRAIN_SECONDS
        while remaining > 0 and time.monotonic() < deadline:
            chunk = self.rfile.read1(min(remaining, 65536))
            if not chunk:
                return
            remaining -= len(chunk)


class ServerHandle:
    """What `ready` receives: where the server listens and a way to stop it."""

    def __init__(self, host, port, stop):
        self.host = host
        self.port = port
        self.url = "http://%s:%d" % ("[%s]" % host if ":" in host else host, port)
        self._stop = stop

    def stop(self):
        self._stop.set()


def _check_arguments(host, port, today):
    if not isinstance(host, str):
        raise ValidationError("host must be text, got '%s'" % (host,))
    if not isinstance(port, int) or isinstance(port, bool) or not 0 <= port <= 65535:
        raise ValidationError("port must be a whole number from 0 to 65535, got '%s'" % (port,))
    if today is not None and (not isinstance(today, datetime.date) or isinstance(today, datetime.datetime)):
        raise ValidationError("today must be a date, got '%s'" % (today,))


def serve(db_path, host="127.0.0.1", port=0, today=None, ready=None, stop=None):
    """Serve the book over HTTP until SIGINT/SIGTERM (or `stop`, a threading.Event, is set); returns 0.

    `ready(handle)`, when given, is called once the server listens and its first line has been printed."""
    _check_arguments(host, port, today)
    with Store.open(db_path) as store:
        store.info()  # raises for a book that needs `db migrate`
    stop = stop if stop is not None else threading.Event()
    saved = {}
    if threading.current_thread() is threading.main_thread():
        for sig in (signal.SIGINT, signal.SIGTERM):
            saved[sig] = signal.signal(sig, lambda signum, frame: stop.set())
    httpd = None
    try:
        cls = _Server6 if ":" in host else _Server
        try:
            httpd = cls((host, port), _Handler, db_path, today)
        except (OSError, OverflowError) as exc:
            raise ConflictError("cannot listen on %s port %s: %s" % (host, port, getattr(exc, "strerror", None) or exc)) from None
        real = httpd.server_address[1]
        shown = host or httpd.server_address[0]
        handle = ServerHandle(shown, real, stop)
        thread = threading.Thread(target=httpd.serve_forever, kwargs={"poll_interval": 0.05}, daemon=True)
        thread.start()
        try:
            sys.stdout.write("tallybook listening on %s\n" % handle.url)
            sys.stdout.flush()
            if ready is not None:
                ready(handle)
            while not stop.wait(0.1):
                pass
        finally:
            httpd.shutdown()
            thread.join(SHUTDOWN_WAIT)
            httpd.server_close()
            httpd.wait_idle(SHUTDOWN_WAIT)
    finally:
        if httpd is not None:
            httpd.server_close()
        for sig, old in saved.items():
            signal.signal(sig, old)
    return 0

